    --yellow:#f5c400;
    --black:#111111;
    --white:#ffffff;
    --grey:#e8e8e8;
    --line:10px;
  }
  *{box-sizing:border-box;margin:0;padding:0;}
  html{scroll-behavior:smooth;}
  body{
    font-family:'Libre Franklin',Arial,sans-serif;
    color:var(--black);
    background:var(--white);
    line-height:1.55;
  }
  h1,h2,h3,.label{font-family:'Archivo',Arial,sans-serif;}

  /* ---- Mondrian grid canvas ---- */
  .mondrian{
    display:grid;
    grid-template-columns:repeat(12,1fr);
    grid-template-rows:repeat(16,minmax(0,auto));
    gap:var(--line);
    background:var(--black);
    padding:var(--line);
  }
  .cell{background:var(--white);}
  .cell.red{background:var(--red);}
  .cell.blue{background:var(--blue);}
  .cell.yellow{background:var(--yellow);}
  .cell.grey{background:var(--grey);}

  /* ---- Hero ---- */
  .hero{
    grid-column:1/13;
    grid-row:1/5;
    display:flex;
    flex-direction:column;
    justify-content:center;
    padding:clamp(1.5rem,4vw,3.5rem);
  }
  .hero .kicker{
    font-family:'Archivo',sans-serif;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.14em;
    font-size:.8rem;
    margin-bottom:1rem;
    display:inline-block;
    background:var(--black);
    color:var(--white);
    padding:.35rem .7rem;
    width:max-content;
  }
  .hero h1{
    font-size:clamp(1.9rem,5.2vw,3.6rem);
    font-weight:700;
    line-height:1.05;
    letter-spacing:-.01em;
    max-width:16ch;
  }
  .hero .sub{
    margin-top:1.1rem;
    font-size:clamp(1rem,1.6vw,1.2rem);
    max-width:48ch;
  }
  .hero .sub b{font-weight:600;}

  /* ---- Info blocks ---- */
  .block{
    padding:clamp(1.2rem,2.6vw,2rem);
    display:flex;
    flex-direction:column;
    justify-content:center;
    gap:.5rem;
  }
  .block .label{
    font-size:.72rem;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.16em;
    opacity:.75;
  }
  .block h2{font-size:clamp(1.15rem,2vw,1.5rem);font-weight:700;line-height:1.15;}
  .block p{font-size:.98rem;}
  .block.on-dark{color:var(--white);}
  .block.on-dark .label{opacity:.85;}
  .block.on-yellow{color:var(--black);}

  /* ---- Layout map ---- */
  .painter{grid-column:1/8;grid-row:5/9;}
  .year{grid-column:8/13;grid-row:5/7;background:var(--yellow);}
  .movement{grid-column:8/13;grid-row:7/9;background:var(--black);}
  .matter{grid-column:1/8;grid-row:9/13;background:var(--red);}
  .principle{grid-column:8/13;grid-row:9/13;}

  /* ---- The picture: miniature of the composition ---- */
  .mini{
    display:grid;
    grid-template-columns:1fr 1fr;
    grid-template-rows:1fr 1fr;
    gap:6px;
    background:var(--black);
    padding:6px;
    width:min(220px,60%);
    aspect-ratio:1/1;
    margin-bottom:.4rem;
